using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates global-motion decoding on a real six-frame 128x128 AV1/IVF clip (a rotating, zooming and
/// panning pattern encoded by aomenc with global motion enabled): the inter frames carry ROTZOOM
/// global-motion models whose parameters are subexponentially coded against the primary reference's
/// models, GLOBALMV blocks resolve their vector from the model at the block centre, and blocks of at
/// least 8x8 (16x16 for chroma) with a warpable model are predicted by the affine warp kernel instead
/// of translational motion compensation. Every decoded frame's luma and chroma planes must be exactly
/// equal to dav1d's decoded output.
/// </summary>
public class Av1GlobalMotionDecodeTests
{
    private const string ClipIvfBase64 =
        "";

    private static readonly string[] Dav1dLumaBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] Dav1dUBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    private static readonly string[] Dav1dVBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
    ];

    [Fact]
    public void DecodeAllFrames_GlobalMotionClip_MatchesDav1dExactly()
    {
        using MemoryStream stream = new(Convert.FromBase64String(ClipIvfBase64));
        List<Av1TileDecoder> frames = Av1DecoderCore.DecodeAllFrames(stream);

        Assert.Equal(6, frames.Count);
        for (int i = 0; i < frames.Count; i++)
        {
            Assert.Equal(Convert.FromBase64String(Dav1dLumaBase64[i]), Crop(frames[i].Luma));
            Assert.Equal(Convert.FromBase64String(Dav1dUBase64[i]), Crop(frames[i].ChromaU));
            Assert.Equal(Convert.FromBase64String(Dav1dVBase64[i]), Crop(frames[i].ChromaV));
        }
    }

    private static byte[] Crop(Av1Plane plane)
    {
        byte[] result = new byte[plane.CropWidth * plane.CropHeight];
        for (int y = 0; y < plane.CropHeight; y++)
        {
            plane.Samples.AsSpan(y * plane.Width, plane.CropWidth).CopyTo(result.AsSpan(y * plane.CropWidth));
        }

        return result;
    }
}
